  'guide.reports.title': 'Read reports',
  'guide.create.why': 'Everything else hangs off the organisation, so start here. You become its owner.',
  'guide.venues.why': 'Sessions, courts and fees are tied to a venue, so add the places you train before you plan programmes.',
  'guide.staff.why': 'Give coaches, front desk and finance their own access. Each person only sees what their role needs.',
  'guide.suppliers.why': 'Keep maintenance contractors and kit suppliers in one place, linked to the venues they serve, with requests tracked to done.',
  'guide.programmes.why': 'A programme is what families buy: a squad, a term course or a camp, with a price and places.',
  'guide.coaches.why': 'Bring coaches in as staff, contractors or revenue-share partners, and agree the terms in writing.',
  'guide.students.why': 'Move people from enquiry to enrolled. Parents and guardians consent for children.',
  'guide.classes.why': 'See today and the week at a glance, take attendance and keep make-ups and cancellations visible.',
  'guide.tax.why': 'Know the tax collected and paid, with your own tax rules and tax details on invoices.',
  'guide.revenue.why': 'Agree how money is shared with coaches and how shared costs are spread across programmes.',
  'guide.reports.why': 'See outcomes, retention, finance health and partners on the executive home, and export what you need.',
