  'guide.accreditation.title': 'Manage accreditation and audits',
  'guide.accreditation.why': 'Track every external accreditation, licence and quality mark your academy holds, keep the evidence for each one linked to records you already maintain, and run audits with findings and corrective actions that cannot be quietly changed.',
  'guide.accreditation.s1': 'Open Academy, then Accreditation, and tap Configure to add a framework: the accrediting body, type, level, owner, renewal cycle and reminder lead time.',
  'guide.accreditation.s2': 'Open the framework, choose Evidence, add what it requires, then link coach credentials and compliance records. Nothing is copied, and validity is read live.',
  'guide.accreditation.s3': 'Tap Schedule audit, choose the type, date and areas to verify, and optionally name an inspector, who sees that audit only.',
  'guide.accreditation.s4': 'Record each finding with its severity and corrective actions, give every action an owner and a due date, and mark them done as the work is finished.',
  'guide.accreditation.s5': 'Resubmit once every high and medium finding is resolved, then record the inspector decision. Every step is kept in a locked trail.',
