  'guide.inclusive_delivery.why': 'Connect accommodations, qualified coaches and accessible venues before each session, so every athlete trains safely and the right support is in place before the first whistle.',
  'guide.inclusive_delivery.s1': 'Open Academy, then Inclusion to configure which need types a programme supports and what venue features are required.',
  'guide.inclusive_delivery.s2': 'After enrolling an athlete, the enrolment flow prompts guardians or the athlete to share their operational needs with the coaching team.',
