  'guide.para_doctor.title': 'Para-athlete clinical coordination',
  'guide.para_doctor.why': 'Provide specialist clinical care to para-athletes by declaring sport-specific expertise, using structured consult templates, managing referral workflows for prosthetists and rehabilitation clinicians, and sharing nonclinical operational summaries — always with athlete consent and entirely separate from classification.',
  'guide.para_doctor.s1': 'Open Doctor workspace → Adaptive tab, declare your para-sport specialisms, then create consult templates for each relevant sport.',
  'guide.para_doctor.s2': 'Create a para episode when you consult with an adaptive athlete, linking it to the appropriate sport and template.',
  'guide.para_doctor.s3': 'Use Health → Referrals to refer to prosthetists, rehabilitation clinicians or sports medicine providers as part of the para-athlete\'s care pathway.',
  'guide.para_doctor.s4': 'Draft a nonclinical support summary for operational staff (access needs, emergency contacts) and send it to the athlete for consent.',
  'guide.para_doctor.s5': 'The athlete approves or declines the summary from their Health → Support tab, and can revoke individual access at any time.',
